export const SATPANCHASIKA_COLOPHON = '॥ इति वराहमिहिरात्मजपृथुयशोविरचिता षट्पञ्चाशिका समाप्ता ॥'

/** 7.7 and 7.8 share one gist in the source. */
const MEANING_7_7_8 = 'Whom is the querist thinking of? Read the house of the strongest planet: 1st = himself, 3rd = brother, 5th = child, 4th = mother or sister, 6th = enemy, 7th = wife, 9th = a religious person, 10th = guru. A strong rising-navāṃśa lord in the lagna = himself; its friend = a friend; its enemy = an enemy.'

export const SATPANCHASIKA_SLOKAS: SatpanchasikaSloka[] = [
  // ── Chapter 1 ──
  { id: '1.1', chapter: 1, sanskrit: 'प्रणिपत्य रविं मूर्ध्ना वराहमिहिरात्मजेन पृथुयशसा । प्रश्ने कृतार्थगहना परार्थमुद्दिश्य सद्यशसा ॥१॥', meaning: 'Bowing his head to the Sun, Pṛthuyaśas, son of Varāhamihira, writes this compact, meaning-dense work on praśna for the benefit of others.' },
  { id: '1.2', chapter: 1, sanskrit: 'च्युतिर्विलग्नाद्धिबुकाच्च वृद्धिर्मध्यात्प्रवासोऽस्तमयान्निवृत्तिः । वाच्यं ग्रहैः प्रश्नविलग्नकालाद्गृहं प्रविष्टो हिबुके प्रवासी ॥२॥', meaning: 'Fall from position is judged from the lagna, growth/prosperity from the 4th, going away from the 10th, return from the 7th. The traveller reaches home when a planet enters the 4th.' },
  { id: '1.3', chapter: 1, sanskrit: 'यो यो भावः स्वामिदृष्टो युतो वा सौम्यैर्वा स्यात्तस्य तस्यास्ति वृद्धिः । पापैरेवं तस्य भावस्य हानिर्निर्देष्टव्या पृच्छतां जन्मतो वा ॥३॥', meaning: 'Any bhāva joined or aspected by its own lord or by benefics flourishes; joined or aspected by malefics, it suffers. Applies to both praśna and birth charts.' },
  { id: '1.4', chapter: 1, sanskrit: 'सौम्ये विलग्ने यदि वास्य वर्गे शीर्षोदये सिद्धिमुपैति कार्यम् । अतो विपर्यस्तमसिद्धिहेतुः कृच्छ्रेण संसिद्धिकरं विमिश्रम् ॥४॥', meaning: 'A benefic in the lagna (or rising in a benefic\'s varga) with a śīrṣodaya sign rising = success. The reverse (malefic, pṛṣṭhodaya) = failure. Mixed = success only with difficulty.' },
  { id: '1.5', chapter: 1, sanskrit: 'होरास्थितः पूर्णतनुः शशाङ्को जीवेन दृष्टो यदि वा सितेन । क्षिप्रं प्रनष्टस्य करोति लब्धिं लाभोपयातो बलवाञ्छुभश्च ॥५॥', meaning: 'A full Moon in the lagna aspected by Jupiter or Venus brings quick recovery of what is lost. So does a strong benefic in the 11th.' },
  { id: '1.6', chapter: 1, sanskrit: 'स्वांशे विलग्ने यदि वा त्रिकोणे स्वांशे स्थितः पश्यति धातुचिन्ताम् । परांशकस्थश्च करोति जीवं मूलं परांशोपगतः परांशम् ॥६॥', meaning: 'A planet in its own navāṃśa aspecting its own navāṃśa in the lagna, 5th or 9th = the query is about a mineral (dhātu). In another\'s navāṃśa aspecting its own = a living being (jīva). In another\'s aspecting another\'s = a plant/root (mūla).' },
  { id: '1.7', chapter: 1, sanskrit: 'धातुं मूलं जीवमित्योजराशौ युग्मे विन्द्यादेतदेव प्रतीपम् । लग्ने योऽंशस्तत्क्रमाद्गण्य एव संक्षेपोऽयं विस्तरात्तत्प्रभेदः ॥७॥', meaning: 'In an odd sign the nine navāṃśas run mineral, root, living (repeated three times); in an even sign the order reverses. Count to the rising navāṃśa to see what the query concerns.' },

  // ── Chapter 2 ──
  { id: '2.1', chapter: 2, sanskrit: 'वृषसिंहवृश्चिकघटैर्विलग्नगैः स्थानं गमागमौ नास्ति । न मृतं न चापि नष्टं न रोगशान्तिर्न चाभिभवः ॥१॥', meaning: 'A fixed sign rising (Taurus, Leo, Scorpio, Aquarius) = gaining a position; no going or coming, no death, no loss, no cure of disease, no defeat. Things stay as they are.', checkAgainstPrint: true },
  { id: '2.2', chapter: 2, sanskrit: 'तद्विपरीतं तु चरैर्द्विशरीरैर्मिश्रितं फलं भवति । लग्नेन्द्वोर्वक्तव्यं शुभदृष्ट्या शोभनमतोऽन्यत् ॥२॥', meaning: 'A movable sign rising gives the reverse of 2.1; a dual sign gives mixed results (first half like fixed, second half like movable). Benefic aspect on lagna and Moon = good; malefic = bad.' },
  { id: '2.3', chapter: 2, sanskrit: 'सुतशत्रुगतैः पापैः शत्रुर्मार्गान्निवर्तते । चतुर्थगैरपि प्राप्तः शत्रुर्भग्नो निवर्तते ॥३॥', meaning: 'Malefics in the 5th and 6th = the enemy turns back midway. Malefics in the 4th = the enemy arrives but is beaten and retreats.' },
  { id: '2.4', chapter: 2, sanskrit: 'झषालिकुम्भकर्कटा रसातले यदा स्थिताः । रिपोः पराजयस्तदा चतुष्पदैः पलायनम् ॥४॥', meaning: 'Pisces, Scorpio, Aquarius or Cancer as the 4th house = defeat of the enemy. A quadruped sign there = the enemy flees.' },
  { id: '2.5', chapter: 2, sanskrit: 'चरोदये शुभः स्थितः शुभं करोति यायिनाम् । अशोभनैरशोभनं स्थिरोदयेऽपि वा शुभम् ॥५॥', meaning: 'A benefic in a rising movable sign = good for the one setting out; a malefic there = harm. A malefic in a rising fixed sign can still be good (per Utpala, if it is that planet\'s own, exaltation or friendly sign).' },
  { id: '2.6', chapter: 2, sanskrit: 'स्थिरे शशी चरोदये न चागमो रिपोर्यदा । तदागमं रिपोर्वदेद्विपर्यये विपर्ययम् ॥६॥', meaning: 'Movable lagna with Moon in a fixed sign = the enemy will not come. Fixed lagna with Moon in a movable sign = the enemy will come.' },
  { id: '2.7', chapter: 2, sanskrit: 'स्थिरे तु लग्नमागते द्विरात्मके तु चन्द्रमाः । निवर्तते रिपुस्तदा सुदूरमागतोऽपि सन् ॥७॥', meaning: 'Fixed lagna with Moon in a dual sign = the enemy turns back even after coming a long way.' },
  { id: '2.8', chapter: 2, sanskrit: 'चरे शशी लग्नगतो द्विदेहः पथोऽर्धमागत्य निवर्तते रिपुः । विपर्यये चागमनं द्विधा स्यात्पराजयः स्यादशुभेक्षिते तु ॥८॥', meaning: 'Moon in a movable sign, dual lagna = the enemy comes halfway and returns. Reverse (movable lagna, Moon in dual) = he comes; if both are malefic-aspected, there is a clash and defeat.' },
  { id: '2.9', chapter: 2, sanskrit: 'अर्कार्किज्ञसितानामेकोऽपि चरोदये यदा भवति । प्रवदेत्तदाशुगमनं वक्रगतैर्नेति वक्तव्यम् ॥९॥', meaning: 'Even one of Sun, Saturn, Mercury or Venus in a rising movable sign = a quick march. If that planet is retrograde, no movement.' },
  { id: '2.10', chapter: 2, sanskrit: 'स्थिरोदये जीवशनैश्चरेक्षिते गमागमौ नैव वदेच्च पृच्छतः । त्रिपञ्चषष्ठा रिपुसङ्गमाय पापाश्चतुर्था विनिवर्तनाय ॥१०॥', meaning: 'Fixed lagna aspected by Jupiter and Saturn = predict neither going nor coming. Malefics in 3rd, 5th, 6th = a clash with the enemy; malefics in the 4th = the enemy retreats.' },
  { id: '2.11', chapter: 2, sanskrit: 'नागच्छति परचक्रं यदार्कचन्द्रौ चतुर्थभवनस्थौ । बुधगुरुशुक्रा हिबुके यदा तदा शीघ्रमायाति ॥११॥', meaning: 'Sun and Moon in the 4th = the enemy army does not come. Mercury, Jupiter and Venus in the 4th = it comes quickly.' },
  { id: '2.12', chapter: 2, sanskrit: 'मेषधनुःसिंहवृषा यद्युदयस्था भवन्ति हिबुके वा । शत्रुर्निवर्तते तदा ग्रहसहिता वा वियुक्ता वा ॥१२॥', meaning: 'Aries, Sagittarius, Leo or Taurus rising or in the 4th = the enemy retreats, whether or not planets occupy it.' },
  { id: '2.13', chapter: 2, sanskrit: 'स्थिरराशौ यद्युदये शनिगुरू वा स्थितस्तदा शत्रुः । उदये रविगुरू वा चरराशौ स्यात्तदागमनम् ॥१३॥', meaning: 'Saturn or Jupiter in a rising fixed sign = the enemy halts where he is. Sun or Jupiter in a rising movable sign = the enemy arrives.' },
  { id: '2.14', chapter: 2, sanskrit: 'ग्रहः सर्वोत्तमबलो लग्नाद्यस्मिन् गृहे स्थितः । मासैस्तत्तुल्यसंख्याकैर्निवृत्तिं यातुरादिशेत् ॥१४॥', meaning: 'Find the strongest planet and count its house from the lagna; the one who set out returns in that many months.' },
  { id: '2.15', chapter: 2, sanskrit: 'चरांशस्थे ग्रहे तस्मिन् कालमेवं विनिर्दिशेत् । द्विगुणं स्थिरभागस्थे त्रिगुणं द्व्यात्मकांशके ॥१५॥', meaning: 'That period holds if the planet is in a movable navāṃśa; double it for a fixed navāṃśa, triple it for a dual one.' },
  { id: '2.16', chapter: 2, sanskrit: 'यातुर्विलग्नाज्जामित्रभवनाधिपतिर्यदा । करोति वक्रमावृत्तिः कालान्तं ब्रुवते परे ॥१६॥', meaning: 'Other teachers say the traveller returns when the 7th lord from the praśna lagna turns retrograde.' },
  { id: '2.17', chapter: 2, sanskrit: 'उदयर्क्षाच्चन्द्रर्क्षं भवति च यावद्दिनानि तावद्भिः । आगमनं स्याच्छत्रोर्यदि मध्ये न ग्रहः कश्चित् ॥१७॥', meaning: 'Count signs from the lagna to the Moon; the enemy arrives in that many days, provided no planet sits between them.' },

  // ── Chapter 3 ──
  { id: '3.1', chapter: 3, sanskrit: 'दशमोदयसप्तमगाः सौम्या नगराधिपस्य विजयकराः । आरार्की ज्ञगुरुसिताः प्रभङ्गदौ विजयदा नवमे ॥१॥', meaning: 'Benefics in the 10th, 1st and 7th give victory to the defender of the town. In the 9th, Mars and Saturn bring rout; Mercury, Jupiter and Venus bring victory.' },
  { id: '3.2', chapter: 3, sanskrit: 'पौरास्तृतीयभवनाद्धर्माद्वा यायिनः शुभे शुभदाः । व्ययदशमाये पापाः पुरस्य नेष्टाः शुभा यातुः ॥२॥', meaning: 'The six houses from the 3rd belong to the townspeople; the six from the 9th to the attacker. Benefics in a side\'s houses favour that side. Malefics in the 12th, 10th, 11th harm the town and help the attacker.' },
  { id: '3.3', chapter: 3, sanskrit: 'नृराशिसंस्था हृदये शुभाः स्युर्व्ययायसंस्थाश्च यदा भवन्ति । तदाशु सन्धिं प्रवदेन्नृपाणां पापैर्द्विदेहोपगतैर्विरोधम् ॥३॥', meaning: 'Benefics in human (biped) signs in the 1st, 12th and 11th = a quick peace treaty. Malefics in dual signs = the hostility continues.' },
  { id: '3.4', chapter: 3, sanskrit: 'केन्द्रोपगताः सौम्याः सौम्यैर्दृष्टा नृलग्नगाः प्रीतिम् । कुर्वन्ति पापदृष्टाः पापास्तेष्वेव विपरीतम् ॥४॥', meaning: 'Benefics in kendras in human signs, aspected by benefics = friendship between the parties. Malefics there aspected by malefics = continued war.' },
  { id: '3.5', chapter: 3, sanskrit: 'द्वितीये वा तृतीये वा गुरुशुक्रौ यदा तदा । आश्वेवागच्छते सेना प्रवासी च न संशयः ॥५॥', meaning: 'Jupiter and Venus (together or singly) in the 2nd or 3rd = the army returns soon, and so does the traveller.' },

  // ── Chapter 4 ──
  { id: '4.1', chapter: 4, sanskrit: 'केन्द्रत्रिकोणेषु शुभस्थितेषु पापेषु केन्द्राष्टमवर्जितेषु । सर्वार्थसिद्धिं प्रवदेन्नराणां विपर्ययस्थेषु विपर्ययः स्यात् ॥१॥', meaning: 'Benefics in kendras and trikonas, malefics outside the kendras and the 8th = every aim fulfilled. The reverse placement = the reverse result.' },
  { id: '4.2', chapter: 4, sanskrit: 'त्रिपञ्चलाभास्तमयेषु सौम्या लाभप्रदा नेष्टफलाश्च पापाः । तुलाथ कन्या मिथुनं घटश्च नृराशयस्तेषु शुभं वदन्ति ॥२॥', meaning: 'Benefics in the 3rd, 5th, 11th, 7th = gain; malefics there = loss. Libra, Virgo, Gemini, Aquarius are the human signs; benefics in them are good.' },
  { id: '4.3', chapter: 4, sanskrit: 'स्थानप्रदा दशमसप्तमगाश्च सौम्या मानार्थदाः स्वसुतलग्नगता भवन्ति । पापा व्ययायसहिता न शुभप्रदाः स्युर्लग्ने शशी न शुभदो दशमे शुभश्च ॥३॥', meaning: 'Benefics in the 10th and 7th give a position; in the 2nd, 5th or 1st, honour and wealth. Malefics in the 12th and 11th give no good. The Moon in the lagna is not good; in the 10th she is good.' },
  { id: '4.4', chapter: 4, sanskrit: 'इन्दुं द्विसप्तदशमायरिपुत्रिसंस्थं पश्येद्गुरुः शुभफलं प्रमदाकृतं स्यात् । लग्नत्रिधर्मसुतनैधनगाश्च पापाः कार्यार्थनाशभयदाः शुभदाः शुभाश्च ॥४॥', meaning: 'Moon in the 2nd, 7th, 10th, 11th, 6th or 3rd aspected by Jupiter = good fortune through a woman. Malefics in the 1st, 3rd, 9th, 5th, 8th = failure, loss and fear; benefics there = good.' },
  { id: '4.5', chapter: 4, sanskrit: 'शुभग्रहाः सौम्यनिरीक्षिताश्च विलग्नसप्ताष्टमपञ्चमस्थाः । त्रिषड्दशाये च निशाकरः स्याच्छुभं भवेद्रोगनिपीडितानाम् ॥५॥', meaning: 'Benefics in the 1st, 7th, 8th, 5th aspected by benefics, with the Moon in the 3rd, 6th, 10th or 11th = a sick person recovers.' },

  // ── Chapter 5 ──
  { id: '5.1', chapter: 5, sanskrit: 'दूरगतस्यागमनं सुतधनसहजस्थितैर्ग्रहैर्लग्नात् । सौम्यैर्नष्टप्राप्तिं लघ्वागमनं गुरुसिताभ्याम् ॥१॥', meaning: 'Planets in the 5th, 2nd and 3rd = return of one gone far away. Benefics there = the lost thing or missing person is found. Jupiter and Venus there = a very quick return.' },
  { id: '5.2', chapter: 5, sanskrit: 'जामित्रे त्वथवा षष्ठे ग्रहः केन्द्रेऽथ वाक्पतिः । प्रोषितागमनं विद्यात्त्रिकोणे ज्ञे सितेऽपि वा ॥२॥', meaning: 'Any planet in the 7th or 6th with Jupiter in a kendra = the absent person returns. Mercury or Venus in a trikona (5th/9th) = the same.' },
  { id: '5.3', chapter: 5, sanskrit: 'अष्टमस्थे निशानाथे कण्टकैः पापवर्जितैः । प्रवासी सुखमायाति सौम्यैर्लाभसमन्वितः ॥३॥', meaning: 'Moon in the 8th with kendras free of malefics = the traveller returns safely. Benefics in the kendras = he returns with gain.' },
  { id: '5.4', chapter: 5, sanskrit: 'पृष्ठोदये पापनिरीक्षिते वा पापास्तृतीये रिपुकेन्द्रगे वा । सौम्यैरदृष्टा वधबन्धदाः स्युर्नष्टा विनष्टा मुषिताश्च वाच्याः ॥४॥', meaning: 'Pṛṣṭhodaya lagna aspected by malefics = harm and confinement. Malefics unaspected by benefics: in the 3rd = he has moved on elsewhere; in the 6th = lost or dead; in a kendra = robbed.' },
  { id: '5.5', chapter: 5, sanskrit: 'ग्रहो विलग्नाद्यतमे गृहे तु तेनाहता द्वादश राशयः स्युः । तावद्दिनान्यागमनस्य विद्यान्निवर्तनं वक्रगतैर्ग्रहैस्तु ॥५॥', meaning: 'Count from the lagna to the first sign holding a planet; multiply by 12 = days until return. If that planet is retrograde, the count itself (not ×12) gives the days.' },

  // ── Chapter 6 ──
  { id: '6.1', chapter: 6, sanskrit: 'स्थिरोदये स्थिरांशे वा वर्गोत्तमगतेऽपि वा । स्थितं तत्रैव तद्द्रव्यं स्वकीयेनैव चोरितम् ॥१॥', meaning: 'Fixed sign rising, fixed navāṃśa rising, or vargottama navāṃśa rising = taken by someone of the owner\'s own people, and it is still in that place.' },
  { id: '6.2', chapter: 6, sanskrit: 'आदिमध्यावसानेषु द्रेक्काणेषु विलग्नतः । द्वारदेशे तथा मध्ये गृहान्ते च वदेद्धनम् ॥२॥', meaning: 'First drekkāṇa rising = near the door; middle = middle of the house; last = the back/end of the house.' },
  { id: '6.3', chapter: 6, sanskrit: 'पूर्णः शशी लग्नगतः शुभो वा शीर्षोदये सौम्यनिरीक्षितश्च । नष्टस्य लाभं कुरुते तदाशु लाभोपयातो बलवाञ्छुभश्च ॥३॥', meaning: 'Full Moon in the lagna, or a benefic in a rising śīrṣodaya sign aspected by benefics = quick recovery. A strong benefic in the 11th = the same.' },
  { id: '6.4', chapter: 6, sanskrit: 'दिग्वाच्या केन्द्रगतैरसम्भवे वा वदेद्विलग्नर्क्षात् । मध्याच्च्युतैर्विलग्नान्नवांशकैर्योजना वाच्या ॥४॥', meaning: 'Direction = from the planet in a kendra (the strongest if several); if none, from the lagna sign. Distance in yojanas = how many navāṃśas the rising point has moved from the middle (5th) navāṃśa.', datedContent: true },
  { id: '6.5', chapter: 6, sanskrit: 'अंशकाज्ज्ञायते द्रव्यं द्रेक्काणैस्तस्कराः स्मृताः । राशिभ्यः कालदिग्देशा वयो जातिश्च लग्नपात् ॥५॥', meaning: 'Navāṃśa → the object; drekkāṇa → the thief\'s appearance; rising sign → time, direction and place; lagna lord → the thief\'s age and class.', datedContent: true },

  // ── Chapter 7 ──
  { id: '7.1', chapter: 7, sanskrit: 'विषमस्थितेऽर्कपुत्रे सुतस्य जन्मान्यथाङ्गनायाश्च । लभ्या वरस्य नारी समस्थितेऽतोऽन्यथा वामम् ॥१॥', meaning: 'Saturn in an odd house from the lagna = birth of a son; otherwise a daughter. For a marriage query, Saturn in an even house = the bride is obtained; in an odd house = not.' },
  { id: '7.2', chapter: 7, sanskrit: 'गुरुरविसौम्यैर्दृष्टस्त्रिसुतमदायारिगः शशी लग्नात् । भवति च विवाहकर्ता त्रिकोणकेन्द्रेषु वा सौम्याः ॥२॥', meaning: 'Moon in the 3rd, 5th, 7th, 11th or 6th aspected by Jupiter, Sun and Mercury = the marriage takes place. Benefics in trikonas and kendras = the same.' },
  { id: '7.3', chapter: 7, sanskrit: 'चन्द्रार्कयोः सप्तमगौ सितार्की सुखेऽष्टमे वापि तथा विलग्नात् । द्वितीयदुश्चिक्यगतौ तथा च वर्षासु वृष्टिं प्रवदेन्नराणाम् ॥३॥', meaning: 'In the rainy season: Venus 7th from the Moon and Saturn 7th from the Sun, or the two in the 4th and 8th, or in the 2nd and 3rd from the lagna = rain.' },
  { id: '7.4', chapter: 7, sanskrit: 'सौम्या जलराशिस्थास्तृतीयधनकेन्द्रगाः सिते पक्षे । चन्द्रे वाप्युदयगते जलराशिस्थे वदेद्वर्षम् ॥४॥', meaning: 'In the bright fortnight, benefics in watery signs in the 3rd, 2nd or kendras = rain. The Moon rising in a watery sign = the same.' },
  { id: '7.5', chapter: 7, sanskrit: 'पुंवर्गे लग्नगते पुंग्रहदृष्टे बलान्विते पुरुषः । युग्मे स्त्रीग्रहदृष्टे स्त्री बुधयुक्ते तु गर्भयुता ॥५॥', meaning: 'A strong male varga rising, aspected by male planets = a boy. A female varga aspected by female planets = a girl. Mercury in the lagna = the woman is pregnant.' },
  { id: '7.6', chapter: 7, sanskrit: 'कुमारिकां बालशशी बुधश्च वृद्धां शनिः सूर्यगुरू प्रसूताम् । स्त्रीं कर्कशां भौमसितौ विधत्त एवं वयः स्यात्पुरुषेषु चैवम् ॥६॥', meaning: 'Lagna occupied/aspected by the young Moon or Mercury = a girl is meant; Saturn = an old woman; Sun or Jupiter = a woman who has given birth; Mars or Venus = a hard, robust woman. Ages for men are read the same way.', datedContent: true },
  { id: '7.7', chapter: 7, sanskrit: 'आत्मसमं लग्नगतैर्भ्राता सहजस्थितैः सुतः सुतगैः । माता वा भगिनी वा चतुर्थगैः शत्रुगैः शत्रुः ॥७॥', meaning: MEANING_7_7_8 },
  { id: '7.8', chapter: 7, sanskrit: 'भार्या सप्तमसंस्थैर्नवमे धर्माश्रितो गुरुर्दशमे । स्वांशपतिमित्रशत्रुषु तथैव वाच्यं बलयुतेषु ॥८॥', meaning: MEANING_7_7_8 },
  { id: '7.9', chapter: 7, sanskrit: 'चरलग्ने चरभागे मध्याद्भ्रष्टे प्रवासचिन्ता स्यात् । भ्रष्टः सप्तमभवनात्पुनर्निवृत्तो यदि न वक्री ॥९॥', meaning: 'Movable lagna with a movable navāṃśa past the middle one rising = the query is about going abroad. A planet that has just left the 7th: if direct, the idea is dropped / the person returns; if retrograde, not.' },
  { id: '7.10', chapter: 7, sanskrit: 'अस्ते रविसितवक्रैः परजायां स्वां गुरौ बुधे वेश्याम् । चन्द्रे च वयः शशिवत्प्रवदेत्सौरेऽन्त्यजातीनाम् ॥१०॥', meaning: 'The 7th house shows the kind of woman the querist was with: Sun, Venus or Mars = another\'s wife; Jupiter = his own wife; Mercury or Moon = a courtesan; Saturn = a low-status woman. Her age follows the Moon\'s age.', datedContent: true },
  { id: '7.11', chapter: 7, sanskrit: 'मन्दः पापसमेतो लग्नान्नवमे शुभैरयुतदृष्टः । रोगार्तः परदेशे चाष्टमगो मृत्युकर एव ॥११॥', meaning: 'Saturn with a malefic in the 9th, not joined or aspected by benefics = the traveller is ill abroad. The same in the 8th = it is fatal for him.' },
  { id: '7.12', chapter: 7, sanskrit: 'सौम्ययुतोऽर्कः सौम्यैः सन्दृष्टश्चाष्टमर्क्षसंस्थश्च । तस्माद्देशादन्यं गतः स वाच्यः पिता तस्य ॥१२॥', meaning: 'Sun joined with and aspected by benefics in the 8th = the querist\'s father, already abroad, has moved from that country to another.' },
]

const BY_ID = new Map(SATPANCHASIKA_SLOKAS.map(s => [s.id, s]))

export function getSatpanchasikaSloka(id: string): SatpanchasikaSloka | undefined {
  return BY_ID.get(id)
}
